def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = {(r-r0, c-c0) for r, c in pts}
    H = max(r for r, c in shape) + 1
    W = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(h-H+1):
        for c in range(w-W+1):
            if (r, c) == (r0, c0):
                continue
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = 2
    return out
from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Identify each rectangular nested-frame object by its colored bounding box.
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]==0 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
        y0=min(y for y,x in comp); y1=max(y for y,x in comp); x0=min(x for y,x in comp); x1=max(x for y,x in comp)
        # Determine ring colors by sampling each inward bounding-box layer.
        rings=[]
        for d in range((min(y1-y0+1,x1-x0+1)+1)//2):
          vals=[]
          for y,x in comp:
            if min(y-y0,y1-y,x-x0,x1-x)==d: vals.append(grid[y][x])
          if vals:
            color=Counter(vals).most_common(1)[0][0]
            if color not in rings: rings.append(color)
        mapping={rings[i]:rings[-1-i] for i in range(len(rings))}
        for y,x in comp: out[y][x]=mapping.get(grid[y][x],grid[y][x])
    return out

